items = [item for item in items if item["question"] not in remove_questions]

for item in items:
    if item["question"] in medium_to_easy:
        item["difficulty"] = "easy"
    elif item["question"] in hard_to_medium:
        item["difficulty"] = "medium"

for idx, item in enumerate(items, start=1):
    item["id"] = idx

from collections import Counter

assert len(items) == 250
assert Counter(item["difficulty"] for item in items) == Counter({"easy": 75, "medium": 100, "hard": 75})

print(json.dumps(items, ensure_ascii=False))
